"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["68424"],{32879(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.dominio_invalido","status":422,"titulo":"Dom\xednio do fato fora do vocabul\xe1rio fechado"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.dominio_invalido","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["O administrador cadastrou um fato declarado (`POST /api/configuracao/admin/fatos-candidato`) ou derivado por regra (`POST /api/configuracao/admin/fatos-candidato/derivados`), ou alterou a defini\xe7\xe3o de um fato (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), com um `dominio` que n\xe3o pertence ao vocabul\xe1rio fechado. O dom\xednio \xe9 o tipo de dado do fato (UNI-REQ-0143). A compara\xe7\xe3o diferencia mai\xfasculas de min\xfasculas, e os espa\xe7os nas pontas s\xe3o desconsiderados.","A recusa vem na lista `errors` da resposta, com `field` igual a `dominio`. Com o dom\xednio recusado, o que depende dele, como a fonte dos valores e o formato, n\xe3o \xe9 conferido. Nada \xe9 gravado. Um `dominio` vazio recebe [a recusa de dom\xednio obrigat\xf3rio](/erros/uniplus.configuracao.fato_candidato.dominio_obrigatorio). No fato de sistema, que s\xf3 aceita mudar o nome, a descri\xe7\xe3o, a forma de exibi\xe7\xe3o e a prote\xe7\xe3o de dados, o dom\xednio fora do vocabul\xe1rio recebe esta recusa, antes da recusa de [defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)."],"comoResolver":["Envie um destes dom\xednios, escrito exatamente assim, em mai\xfasculas: `SIM_OU_NAO`, `OPCAO`, `NUMERICO`, `TEXTO`, `DATA` ou `ENDERECO`. O fato derivado por regra aceita s\xf3 `SIM_OU_NAO` e `OPCAO`, e o resumo de grupo n\xe3o informa o dom\xednio, porque o infere do fato de membro."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Cadastro de um fato derivado por regra do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);